#include <assert.h>
#include <stdint.h>
#include <string.h>
#include "amtari.h"
struct vdi_fixture{uint16_t opcode;int calls;}; struct line_fixture{int calls;int16_t x1,y1,x2,y2;uint16_t color,style;};
static int32_t vd(void*o,uint16_t op,const int16_t*i,uint16_t ni,const int16_t*p,uint16_t np,int16_t*out,uint16_t oc,uint16_t*no,int16_t*po,uint16_t pc,uint16_t*npo){struct vdi_fixture*f=o;(void)i;(void)ni;(void)p;(void)np;(void)oc;(void)pc;f->opcode=op;++f->calls;out[0]=42;po[0]=320;po[1]=200;*no=1;*npo=2;return 0;}
static int line(void*o,int16_t x1,int16_t y1,int16_t x2,int16_t y2,uint16_t color,uint16_t style){struct line_fixture*f=o;++f->calls;f->x1=x1;f->y1=y1;f->x2=x2;f->y2=y2;f->color=color;f->style=style;return 0;}
static void w16(uint8_t*m,uint32_t a,uint16_t v){m[a]=(uint8_t)(v>>8);m[a+1]=(uint8_t)v;}
static void w32(uint8_t*m,uint32_t a,uint32_t v){w16(m,a,(uint16_t)(v>>16));w16(m,a+2,(uint16_t)v);}
int main(void){struct amtari_context c={0};struct vdi_fixture v={0};struct line_fixture l={0};int16_t out[8]={0},po[8]={0},p[6]={10,20,30,40,50,60},in[1];uint16_t no=0,npo=0,x;uint8_t mem[1024];assert(amtari_init(&c)==0);assert(amtari_vdi_configure(&c,640,400,16)==0);assert(amtari_vdi_dispatch(&c,1,0,0,0,0,out,8,&no,po,8,&npo)==0);assert(no==3&&npo==2&&out[0]==1&&po[0]==639&&po[1]==399);assert(amtari_vdi_line_bind(&c,line,&l)==0);in[0]=3;assert(amtari_vdi_dispatch(&c,15,in,1,0,0,out,8,&no,po,8,&npo)==0);assert(no==1&&out[0]==3);in[0]=5;assert(amtari_vdi_dispatch(&c,17,in,1,0,0,out,8,&no,po,8,&npo)==0);assert(no==1&&out[0]==5);assert(amtari_vdi_dispatch(&c,6,0,0,p,6,out,8,&no,po,8,&npo)==0);assert(l.calls==2);assert(l.x1==30&&l.y1==40&&l.x2==50&&l.y2==60&&l.style==3&&l.color==5);assert(amtari_vdi_bind(&c,vd,&v)==0);assert(amtari_vdi_dispatch(&c,100,0,0,0,0,out,8,&no,po,8,&npo)==0);assert(v.calls==1&&v.opcode==100);
memset(mem,0,sizeof(mem));assert(amtari_guest_memory_bind(&c,mem,sizeof(mem))==0);w16(mem,0x20,0x4e42);w32(mem,0x100,0x140);w32(mem,0x104,0x180);w32(mem,0x108,0x1c0);w32(mem,0x10c,0x200);w32(mem,0x110,0x240);w16(mem,0x140,100);w16(mem,0x142,0);w16(mem,0x146,0);c.cpu.pc=0x20;c.cpu.d[0]=0x0073;c.cpu.d[1]=0x100;assert(amtari_exec_step(&c)==AMTARI_EXEC_RUNNING);assert(c.cpu.pc==0x22);assert(c.cpu.d[0]==0x0073);assert(v.calls==2&&v.opcode==100);assert(amtari_guest_read16(&c,0x200,&x)==0&&x==42);assert(amtari_guest_read16(&c,0x140+8,&x)==0&&x==1);assert(amtari_guest_read16(&c,0x140+4,&x)==0&&x==1);return 0;}
